using Cogpunk.Core.Templates;
using Microsoft.Xna.Framework;
using Terraria;
using Terraria.ID;
using Terraria.ModLoader;

namespace Cogpunk.Content.Coghaven.Tiles
{
	/// <summary>
	/// Bronze Gearwork (2026-11-06): aged bronze machinery with a gear rack running across it, rivets and verdigris: the core of Coghaven's island and its engine deck. Generated by <see cref="Generation.CoghavenPass"/>; seamless clump art from art/coghaven/make_coghaven_art.py.
	/// </summary>
	public class BronzeGearworkTile : CogpunkTile
	{
		public override void SetStaticDefaults() {
			TileID.Sets.GeneralPlacementTiles[Type] = false;   // later world-gen features (other mods) keep off the palace
			Main.tileSolid[Type] = true;
			Main.tileBlockLight[Type] = true;
			DustType = DustID.Copper;
			HitSound = SoundID.Tink;
			AddMapEntry(new Color(138, 93, 34), CreateMapEntryName());
			RegisterItemDrop(ModContent.ItemType<Items.BronzeGearwork>());
		}
	}
}
